def is_undulating(n):
    """
    Checks whether the given number is undulating or not.
    An undulating number is a number where the digits alternate between increasing and decreasing.
    For example, 1212121: 1 < 2 > 1 < 2 > 1 < 2 > 1
    """
    s = str(n)
    if len(s) < 3:
        # Numbers with 1 or 2 digits cannot exhibit an alternating pattern of increase/decrease
        return False

    digits = [int(d) for d in s]

    # Check the pattern: d0 < d1 > d2 < d3 > d4 ... OR d0 > d1 < d2 > d3 < d4 ...

    # Check for pattern starting with increase (d0 < d1)
    is_up_down = True
    for i in range(len(digits) - 1):
        if i % 2 == 0:  # Expected: d_i < d_{i+1} (Up)
            if not (digits[i] < digits[i+1]):
                is_up_down = False
                break
        else:  # Expected: d_i > d_{i+1} (Down)
            if not (digits[i] > digits[i+1]):
                is_up_down = False
                break

    if is_up_down:
        return True

    # Check for pattern starting with decrease (d0 > d1)
    is_down_up = True
    for i in range(len(digits) - 1):
        if i % 2 == 0:  # Expected: d_i > d_{i+1} (Down)
            if not (digits[i] > digits[i+1]):
                is_down_up = False
                break
        else:  # Expected: d_i < d_{i+1} (Up)
            if not (digits[i] < digits[i+1]):
                is_down_up = False
                break

    return is_down_up

