def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # 1. Calculate MSIS (Maximum Sum Increasing Subsequence) ending at each index i
    msis = [arr[i] for i in range(n)]
    for i in range(n):
        for j in range(i):
            if arr[i] > arr[j]:
                msis[i] = max(msis[i], arr[i] + msis[j])

    # 2. Calculate MSIS_rev (Maximum Sum Increasing Subsequence ending at each index i,
    # but considering the array from right to left, which is equivalent to
    # Maximum Sum Decreasing Subsequence starting at i)
    msis_rev = [arr[i] for i in range(n)]
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, i, -1):
            if arr[i] > arr[j]:
                msis_rev[i] = max(msis_rev[i], arr[i] + msis_rev[j])

    # 3. Calculate Maximum Sum Bitonic Subsequence (MSBS)
    # MSBS[i] = MSIS[i] + MSIS_rev[i] - arr[i]
    # We subtract arr[i] because it is counted in both MSIS[i] and MSIS_rev[i]
    max_bs = 0
    for i in range(n):
        current_bs = msis[i] + msis_rev[i] - arr[i]
        max_bs = max(max_bs, current_bs)

    return max_bs

if __name__ == '__main__':
    assert max_sum([1, 15, 51, 45, 33, 100, 12, 18, 9]) == 194
    assert max_sum([1, 2, 3]) == 6
    assert max_sum([3, 2, 1]) == 6
    assert max_sum([10]) == 1

